/// RAII tempdir owner for CLI tests.
///
/// - `base` is a freshly-allocated unique tempdir, which does *not*
///   exist on disk until the caller (or the subprocess) creates it.
/// - `home` is a sibling under `base` reserved for `HOME` override
///   on subprocesses, so config reads don't escape the fixture.
/// - `Drop` removes the whole `base` tree (best-effort).
pub struct CliFixture {
    pub base: PathBuf,
    pub home: PathBuf,
}

impl CliFixture {
    /// Allocate a fresh fixture, creating `home/` so `HOME=...` points
    /// at a real directory, and seed it with a jj user identity.
    ///
    /// The identity is required, not cosmetic: since 0.76.0-5 init
    /// publishes with `jj git push`, which refuses commits that
    /// have no author/committer, and the isolated `HOME` has no
    /// user config to inherit one from.
    pub fn new(tag: &str) -> Self {
        let base = unique_base(tag);
        let home = base.join("home");
        std::fs::create_dir_all(&home).expect("mkdir cli fixture home");
        let jj_cfg = home.join(".config").join("jj");
        std::fs::create_dir_all(&jj_cfg).expect("mkdir cli fixture jj config dir");
        std::fs::write(
            jj_cfg.join("config.toml"),
            "[user]\nname = \"cli-test\"\nemail = \"cli-test@example.com\"\n",
        )
        .expect("write cli fixture jj config");
        CliFixture { base, home }
    }

    /// Build a `vc-x1` `Command` with `HOME` pointed at the
    /// fixture's isolated home dir, so user config can't leak.
    /// `XDG_CONFIG_HOME` and `JJ_CONFIG` are set and cleared on the
    /// child too, either of which would otherwise send jj's config
    /// reads, and its per-repo entries, past the fixture's home.
    pub fn cmd(&self) -> Command {
        let mut c = vc_x1();
        isolate_config(&mut c, &self.home);
        c
    }

    /// Convenience: join a relative path under `base`.
    pub fn path(&self, rel: impl AsRef<Path>) -> PathBuf {
        self.base.join(rel)
    }
}

impl Drop for CliFixture {
    /// Remove the fixture tree on drop. Suppressed when
    /// `$VC_X1_TEST_KEEP` is set: see
    /// `test_tmp_root::should_keep_tempdir`.
    fn drop(&mut self) {
        if should_keep_tempdir() {
            eprintln!("VC_X1_TEST_KEEP set; preserving {}", self.base.display());
        } else {
            let _ = std::fs::remove_dir_all(&self.base);
        }
    }
}

/// Point a child's config at `home`: `HOME` and `XDG_CONFIG_HOME`
/// set to it, and `JJ_CONFIG`, which overrides both, removed. Set on
/// the child alone, never on the test process.
fn isolate_config(cmd: &mut Command, home: &Path) {
    cmd.env("HOME", home)
        .env("XDG_CONFIG_HOME", home.join(".config"))
        .env_remove("JJ_CONFIG");
}

